import os,json,subprocess,socket,stat,time
from pathlib import Path
root=Path("/srv/projects/pink-iptv")
gateway=root/"vpn/gateway"
unit=Path("/etc/systemd/system/pink-vpn.service")
sock=Path("/run/pink-vpn/control.sock")
out={"project":"pink-iptv","status":"BLOCKED","changed":False}
restart_attempted=False
def run(args,seconds=25):
 return subprocess.run(args,capture_output=True,text=True,timeout=seconds)
def states():
 return {n:run(["systemctl","is-active",n],8).stdout.strip() for n in ("ssh","nginx","pink-vpn","pink-iptv-backend","lowcost-europa","fadego-staging","pm2-root","pm2-iptvpn-bot")}
def pid():
 r=run(["systemctl","show","pink-vpn","-p","MainPID","--value"],8)
 try:return int(r.stdout.strip())
 except Exception:return 0
def socket_ok():
 try:
  if not sock.exists() or not stat.S_ISSOCK(sock.stat().st_mode):return False
  with socket.socket(socket.AF_UNIX,socket.SOCK_STREAM) as s:
   s.settimeout(4)
   s.connect(str(sock))
  return True
 except (OSError,TimeoutError):return False
def proc_is_new(p):
 try:
  b=(Path("/proc")/str(p)/"cmdline").read_bytes()
  return b"/srv/projects/pink-iptv/vpn/gateway/pink_vpn_052_gateway.py" in b and b"/etc/pink-vpn" not in b
 except OSError:return False
try:
 if not unit.is_file() or unit.is_symlink() or not gateway.is_dir() or gateway.is_symlink():raise RuntimeError("canonical_gateway_or_unit_invalid")
 t=unit.read_text()
 if t.count(str(gateway))!=3 or "/etc/pink-vpn" in t:raise RuntimeError("canonical_service_config_not_loaded")
 if run(["systemd-analyze","verify",str(unit)],14).returncode:raise RuntimeError("unit_syntax_invalid")
 files=(gateway/"pink_vpn_052_gateway.py",gateway/"pink_vpn_052_install.py")
 for f in files:
  if not f.is_file() or f.is_symlink() or b"/etc/pink-vpn" in f.read_bytes() or b"/var/lib/pink-vpn" in f.read_bytes():raise RuntimeError("python_script_contains_legacy_path")
 baseline=states();oldpid=pid()
 if baseline["pink-vpn"]!="active" or oldpid<=0 or not socket_ok():raise RuntimeError("vpn_process_or_control_socket_unhealthy_before")
 r=run(["systemctl","restart","pink-vpn"],60);restart_attempted=True
 if r.returncode!=0:raise RuntimeError("vpn_service_restart_failed")
 time.sleep(3)
 fresh=states();newpid=pid()
 if fresh!=baseline or newpid<=0 or newpid==oldpid or not proc_is_new(newpid):raise RuntimeError("vpn_unit_or_process_after_restart_failed")
 if not socket_ok():raise RuntimeError("control_unix_socket_after_restart_failed")
 if run(["systemctl","is-enabled","pink-vpn"],8).stdout.strip()!="enabled":raise RuntimeError("vpn_startup_not_enabled")
 out.update(status="RESTART_VERIFIED",changed=True,old_pid=oldpid,new_pid=newpid,canonical_service_exec=True,control_socket_reconnected=True,boot_unit_enabled=True,services_unchanged=True,archived_originals_available=True)
except Exception as e:
 out["reason"]=str(e)[:180]
 if restart_attempted:
  restored=[]
  archive=root/"archive/vpn-code-canonical-20261104"
  for p in (gateway/"pink_vpn_052_gateway.py",gateway/"pink_vpn_052_install.py",unit):
   backup=archive/(p.name+".pre-physical-path")
   try:
    if not backup.is_file():continue
    b=backup.read_bytes();st=p.stat()
    tmp=p.with_name("."+p.name+".rollback.tmp")
    with open(tmp,"xb") as f:f.write(b);f.flush();os.fsync(f.fileno())
    os.chown(tmp,st.st_uid,st.st_gid);os.chmod(tmp,st.st_mode&0o777)
    os.replace(tmp,p);restored.append(str(p))
   except Exception:pass
  try:
   run(["systemctl","daemon-reload"],20)
   run(["systemctl","restart","pink-vpn"],60)
   out["recovery"]="RESTORED_OLD_VPN_ONLINE" if len(restored)==3 and states().get("pink-vpn")=="active" and socket_ok() else "INCOMPLETE"
  except Exception:out["recovery"]="INCOMPLETE"
print(json.dumps(out,sort_keys=True))
if out["status"]!="RESTART_VERIFIED":raise SystemExit(3)
